algorithms.pseudocode:
R = dest_logical_reg, V = result_value
if type(V) == INT:
  digest = lead_zeros_or_ones(V)[2:0] || trail_zeros_or_ones(V)[2:0] || V[5:0]
else if type(V) == FP:
  digest = extract_format_specific_bits(V)
else if type(V) == FLAG:
  digest = V[3:0] || V[3:0] || V[3:0]
Table[R].payload = digest
Table[R].valid = 1
